"use client"

import React from "react"
import { useTranslations } from "next-intl"
import {
    CV_TWO_COLUMN_TEMPLATES,
    type CvDocument,
    type CvTemplate,
} from "@/modules/types/entities/cv"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import { CvHtmlDocument } from "../CvHtmlDocument"

/** The templates the gallery offers, in display order. */
const TEMPLATE_ORDER: ReadonlyArray<CvTemplate> = ["classic", "modern", "sidebar", "minimal"]

/** Props for {@link CvTemplateGalleryModal}. */
export interface CvTemplateGalleryModalProps {
    /** Whether the modal is open. */
    isOpen: boolean
    /** Fired when the modal should open/close. */
    onOpenChange: (isOpen: boolean) => void
    /** The active document ΓÇö its data feeds every live thumbnail. */
    doc: CvDocument
    /** Fired with the picked template; the caller applies it to `style` + closes. */
    onSelect: (template: CvTemplate) => void
}

/**
 * "Template Gallery" ΓÇö a modal grid of LIVE template thumbnails (the user's own CvGalleryPage
 * rendered in each layout via {@link CvHtmlDocument}) + name + an ATS badge.
 * Single-column templates read "ATS-safe"; the two-column one carries a
 * warning (ATS parsers + `.docx` export handle it worse ΓÇö see
 * `CvGalleryPage-TEMPLATES-BRAINSTORM.md`). Picking a card applies the template and closes.
 *
 * Thumbnail mount (`width: 820` + `scale(0.34)` + fixed `h-52` crop) has no finite
 * vocabulary owner ΓÇö held as contract proposal `CvTemplateThumbMount`, not rewritten.
 *
 * @param props - {@link CvTemplateGalleryModalProps}
 */
export const CvTemplateGalleryModal = ({
    isOpen,
    onOpenChange,
    doc,
    onSelect}: CvTemplateGalleryModalProps) => {
    const t = useTranslations()
    const current = doc.style.template ?? "classic"

    const onPick = (template: CvTemplate) => {
        onSelect(template)
        onOpenChange(false)
    }

    const items: Array<GridItem> = TEMPLATE_ORDER.map((template) => {
        const isTwoColumn = CV_TWO_COLUMN_TEMPLATES.has(template)
        const isSelected = current === template
        const name = t(`cv.builder.template.names.${template}`)
        return {
            key: template,
            content: () => (
                <SurfaceCard
                    isSelected={isSelected}
                    onPress={() => onPick(template)}
                    ariaLabel={t("cv.builder.template.selectAria", { name })}
                    body={() => (
                        <StackV
                            principle="card-caption"
                            explain="Thumbnail crop over template caption row ΓÇö not sibling-stack, because the caption belongs to the media above it."
                            items={[
                                () => (
                                    // HOLD: CvTemplateThumbMount ΓÇö live HTML CV scaled into a
                                    // fixed crop. No Measure/PDFView enum owns scale(0.34)├ù820px.
                                    <div aria-hidden className="h-52 overflow-hidden border-b border-default bg-white">
                                        <div
                                            className="pointer-events-none origin-top-left"
                                            style={{ width: 820, transform: "scale(0.34)" }}
                                        >
                                            <CvHtmlDocument doc={{ ...doc, style: { ...doc.style, template } }} />
                                        </div>
                                    </div>
                                ),
                                () => (
                                    <StackH
                                        principle="content-row"
                                        explain="Keeps template name and ATS chip on one baseline so the chip does not drop under the title."
                                        items={[
                                            () => (
                                                <StackV
                                                    principle="title-subtitle"
                                                    explain="Template name over optional Word hint ΓÇö not label-field, because neither line is a form control."
                                                    items={[
                                                        () => (
                                                            <Typography
                                                                size="sm"
                                                                weight="semibold"
                                                                truncate
                                                                text={name}
                                                            />
                                                        ),
                                                        ...(isTwoColumn
                                                            ? [
                                                                () => (
                                                                    <Typography
                                                                        size="xs"
                                                                        color="muted"
                                                                        text={t("cv.builder.template.wordHint")}
                                                                    />
                                                                ),
                                                            ]
                                                            : []),
                                                    ]}
                                                />
                                            ),
                                            () => (
                                                <Chip
                                                    tone={isTwoColumn ? "warning" : "success"}
                                                    text={isTwoColumn ? t("cv.builder.template.atsRisk") : t("cv.builder.template.atsSafe")}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    )}
                />
            ),
        }
    })

    return (
        <ModalShell
            identity={{ tier: "block", component: "CvTemplateGalleryModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={t("cv.builder.template.galleryTitle")}
            size="lg"
            body={() => (
                <Grid
                    columns={{ base: 1, sm: 2 }}
                    principle="sibling-stack"
                    explain="Same-kind peer template tiles ΓÇö not group-boundary, because each card is a repeating peer rather than a section group."
                    items={items}
                />
            )}
        />
    )
}

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"

/** Props for the {@link EntityLink} block. */
export interface EntityLinkProps {
    /** Token text ΓÇö a username, lesson/challenge/course title, etc. */
    label: string
    /**
     * Press handler (the owning feature resolves the entity's route and navigates).
     * Omit ΓåÆ the label renders as non-interactive bold text (e.g. an unresolvable /
     * deleted target), never as a dead link.
     */
    onPress?: () => void
    /** Disable the link while a resolve/navigate is in flight. */
    isPending?: boolean
}

/**
 * An inline entity reference inside a sentence (feed / activity line): the actor
 * or the target. Bold + clickable when an `onPress` is given (owns the link look),
 * bold plain text otherwise. Pure/props-only ΓÇö the feature owns route resolution
 * and passes the press handler; the block owns the styling so feature lines stay
 * style-free.
 *
 * @param props - {@link EntityLinkProps}
 */
export const EntityLink = ({ label, onPress, isPending }: EntityLinkProps) => {
    const interactive = Boolean(onPress) && !isPending

    return (
        <Box
            as="span"
            identity={{ tier: "block", component: "EntityLink" }}
        >
            {interactive ? (
                <Typography
                    size="sm"
                    weight="semibold"
                    isLink
                    text={label}
                    onPress={onPress}
                />
            ) : (
                <Typography
                    size="sm"
                    weight="semibold"
                    text={label}
                />
            )}
        </Box>
    )
}

import React from "react"

/** Props for the {@link StickyBottomBar} block. */
export interface StickyBottomBarProps {
    /** Bar content (typically a price + a primary action). */
    children: React.ReactNode
}

/**
 * A fixed bottom action bar pinned to the viewport edge ΓÇö owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * @param props - {@link StickyBottomBarProps}
 * @see Story: .storybook/stories/blocks/layout/StickyBottomBar/StickyBottomBar.stories
 */
export const StickyBottomBar = ({
    children,
}: StickyBottomBarProps) => {
    return (
        <div className="fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-4 py-3">
            {children}
        </div>
    )
}

import { ArrowLeftIcon } from "@phosphor-icons/react"
import React from "react"
import {
    Button,
} from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"

/** Props for {@link _SubPageHeader} ΓÇö presentational; the back-button aria-label already resolved. */
export interface SubPageHeaderProps {
    /** Page title shown beside the back button. */
    title: string
    /** Optional subtitle; reserved height is three lines; longer text wraps then truncates. */
    description?: string
    /** Called when the back button is pressed. */
    onBack: () => void
    /** Already-localized accessible label for the back button. */
    backAriaLabel: string
}

/**
 * Reusable sub-page header with back navigation, title, and optional description.
 *
 * @param props - {@link SubPageHeaderProps}
 */
export const _SubPageHeader = ({
    title,
    description,
    onBack,
    backAriaLabel,
}: SubPageHeaderProps) => (
    <div className="flex items-center gap-2">
        <Button
            variant="ghost"
            isIconOnly
            aria-label={backAriaLabel}
            onPress={onBack}
            className="shrink-0"
        >
            <ArrowLeftIcon

                className="size-6"
            />
        </Button>
        <div className="min-w-0 flex-1">
            <Typography size="h3" weight="bold" text={title} />
            {description !== undefined ? (
                <div className="mt-1 text-sm text-muted line-clamp-3 overflow-hidden whitespace-normal break-words">
                    {description}
                </div>
            ) : null}
        </div>
    </div>
)

"use client"

import React, { useCallback } from "react"
import { Handle, type Node, type NodeProps, Position } from "@xyflow/react"
import { cn } from "@heroui/react"
import { useRouter } from "next/navigation"
import { useLocale } from "next-intl"
import { CheckCircleIcon } from "@phosphor-icons/react"

import { GlyphMark } from "@/components/atoms/display/GlyphMark"
import { COURSE_MODULE_SLOT_NODE_TYPE, SLOT_NODE_HEIGHT, SLOT_NODE_WIDTH } from "../moduleExpansion"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"

/** React Flow node data for a `courseModuleContent` (lesson) node. */
export type CourseModuleSlotNodeData = {
    /** Parent `courseModule` node id this lesson belongs to. */
    parentModuleId: string
    /** Course mount slug ΓÇö needed to build the lesson URL. */
    courseDisplayId: string
    /** Owning module id ΓÇö part of the lesson URL. */
    moduleId: string
    /** Lesson (content) id this card opens. */
    contentId: string
    /** Lesson title shown on the card. */
    label: string
    /** True when the parent module sits in the left column (handle faces right, toward the module). */
    isLeft: boolean
    /** Whether the viewer has read this lesson. */
    isRead: boolean
}

/** React Flow node type for a `courseModuleContent` (lesson) node. */
export type CourseModuleSlotFlowNode = Node<CourseModuleSlotNodeData, typeof COURSE_MODULE_SLOT_NODE_TYPE>

/**
 * Real lesson card expanded beside a course module. Clicking navigates straight into
 * the lesson reader (the map is a content surface ΓÇö no intermediate preview drawer).
 * Guests are bounced to the authentication modal first. A read flag marks finished lessons.
 * @param props ΓÇö React Flow `NodeProps` for `courseModuleContent` nodes.
 */
export const CourseModuleSlotNode = (props: NodeProps<CourseModuleSlotFlowNode>) => {
    const { data, selected } = props
    const router = useRouter()
    const locale = useLocale()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const authentication = useAuthenticationOverlayState()

    const onOpen = useCallback(() => {
        // gate: guests cannot open the lesson ΓÇö bounce them to the auth modal
        if (!authenticated) {
            authentication.open()
            return
        }
        if (!data.courseDisplayId) {
            return
        }
        router.push(
            pathConfig()
                .locale(locale)
                .course(data.courseDisplayId)
                .learn()
                .module(data.moduleId)
                .content(data.contentId)
                .build(),
        )
    }, [
        authenticated,
        authentication,
        router,
        locale,
        data.courseDisplayId,
        data.moduleId,
        data.contentId,
    ])

    return (
        <button
            type="button"
            onClick={(event) => {
                // keep the click on the card ΓåÆ open lesson; don't let the canvas zoom-handler also fire
                event.stopPropagation()
                onOpen()
            }}
            className={cn(
                "nodrag nopan relative flex items-center justify-center gap-2 rounded-2xl px-3 py-2 text-center",
                "border bg-background/90 text-sm font-medium text-foreground shadow-sm outline-none",
                "transition-all duration-200 hover:border-accent hover:bg-accent/5 hover:shadow-md hover:ring-2 hover:ring-accent/30",
                "focus-visible:ring-2 focus-visible:ring-accent/40",
                "dark:border-zinc-600/80 dark:bg-zinc-900/90 dark:hover:bg-accent-soft dark:hover:ring-accent/40",
                selected && "ring-2 ring-accent",
            )}
            style={{ width: SLOT_NODE_WIDTH, minHeight: SLOT_NODE_HEIGHT }}
        >
            <Handle
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={data.isLeft ? Position.Right : Position.Left}
                type="target"
            />
            {data.isRead ? (
                <GlyphMark icon={CheckCircleIcon} tone="success" />
            ) : null}
            <span className="line-clamp-2 leading-snug">{data.label}</span>
        </button>
    )
}

/** Folder-matching handle for the module-slot node ΓÇö an alias of {@link CourseModuleSlotNode}. */
export const ModuleSlotNode = CourseModuleSlotNode

import React from "react"
import { BookOpenIcon, CodeIcon, FlaskIcon, PlayIcon, PuzzlePieceIcon } from "@phosphor-icons/react"
import { Toolbar, type ToolbarTabItem } from "@/components/composites/navigation/Toolbar"

/**
 * `ContentModeNav` ΓÇö how to view this lesson: modes on the left, code language
 * on the right. Switching mode changes the route, so this is navigation, not a
 * tab/panel pair. A locked mode renders muted but still fires `onModeChange` ΓÇö
 * the screen decides a locked tap opens the paywall. The mode group carries the
 * one accent; the language group is neutral. No `isSkeleton` ΓÇö it is static
 * chrome. The right group appearing is its own leaf; selected mode and lock
 * state are data.
 */

/** The ways a lesson can be looked at. */
export type ContentMode = "content" | "sandbox" | "challenges" | "aiLab"

/**
 * Label + icon per mode. The BLOCK owns this table: it is the vocabulary of the
 * reading experience, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<ContentMode, string> = {
    content: "Content",
    sandbox: "Sandbox",
    challenges: "Challenges",
    aiLab: "AI Lab",
}

// `size-5` ΓÇö the tab's own text is `text-sm` (HeroUI `Tabs.Tab` default, `tabs.css`
// `.apply ... text-sm`), and this icon sits INSIDE that control, so it matches the
// control's own box height (line-height 20px), not the bare glyph size (┬º5a icon=DIV
// case) ΓÇö `size-3.5` would be the icon=TEXT pairing, wrong for an icon inside a tab.
const MODE_ICON: Record<ContentMode, React.ReactNode> = {
    content: <BookOpenIcon aria-hidden focusable="false" className="size-5" />,
    sandbox: <PlayIcon aria-hidden focusable="false" className="size-5" />,
    challenges: <PuzzlePieceIcon aria-hidden focusable="false" className="size-5" />,
    aiLab: <FlaskIcon aria-hidden focusable="false" className="size-5" />,
}

// Same icon on every language tab (doesn't distinguish TS from Go) ΓÇö the trigger
// affordance for "this collapses to a language switcher" below `@app-sm`, not a
// per-language mark. Matches `Toolbar`'s own collapsed-group story convention
// (`RightNeutralCollapsed`, every item sharing one `GlobeIcon`) ΓÇö the collapsed
// `Select` trigger is ICON-ONLY (┬º13c), so a language row with no icon of its own
// would render a blank trigger once `collapseRightOnMobile` is on.
const LANGUAGE_ICON = <CodeIcon aria-hidden focusable="false" className="size-4" weight="bold" />

/** One offered mode ΓÇö whether it is locked. */
export interface ContentModeOption {
    /** Which mode this entry is. */
    mode: ContentMode
    /** `true` ΓåÆ premium and not yet bought: rendered muted, still clickable. */
    isLocked?: boolean
}

/** One entry in the fixed code-language catalog. */
export interface ContentLanguage {
    /** Stable id used as the selection key, e.g. `"typescript"`. */
    key: string
    /** Display label, already localized by the caller. */
    label: string
    /** `true` ΓåÆ this lesson has no body in this language: rendered disabled, not omitted. */
    isDisabled?: boolean
}

/** Props for {@link ContentModeNav}. */
export interface ContentModeNavProps {
    /** Modes this lesson offers, in display order. */
    modes: Array<ContentModeOption>
    /** Which mode is being looked at now. */
    mode: ContentMode
    /**
     * Fired with the mode the reader picked ΓÇö INCLUDING a locked one. The screen
     * decides what a locked pick means (typically: open the paywall instead of
     * navigating). The block never swallows the event.
     */
    onModeChange: (mode: ContentMode) => void
    /**
     * The FULL fixed language catalog (TypeScript/Java/C#/Go, in that order),
     * each carrying its own `isDisabled` ΓÇö a lesson missing a language still
     * lists it, dimmed, rather than shrinking the row (real `src` never hides
     * a language, only greys it out). Fewer than two AVAILABLE (non-disabled)
     * entries ΓåÆ the right group is not drawn at all: a switcher with one live
     * option is a control that cannot do anything.
     */
    languages?: Array<ContentLanguage>
    /** Which language is being read. */
    language?: string
    /** Fired with the language the reader picked. */
    onLanguageChange?: (language: string) => void
    /**
     * Accessible name for the mode row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears loose tabs.
     */
    ariaLabel: string
    /** Accessible name for the language group. Required whenever `languages` is set. */
    languageAriaLabel?: string
}

/**
 * The lesson's mode row. See the file header for why locked modes stay clickable
 * and why this is navigation rather than a tab/panel pair.
 *
 * @param props - {@link ContentModeNavProps}
 */
const ContentModeNav = ({
    modes,
    mode,
    onModeChange,
    languages,
    language,
    onLanguageChange,
    ariaLabel,
    languageAriaLabel,
}: ContentModeNavProps) => {
    const items: Array<ToolbarTabItem> = modes.map((entry) => ({
        key: entry.mode,
        label: MODE_LABEL[entry.mode],
        icon: MODE_ICON[entry.mode],
        // MUTED, not disabled: a locked mode must still receive the click so the
        // screen can open the offer. Disabling it kills the very thing this row is for.
        muted: entry.isLocked,
    }))

    // A switcher with one AVAILABLE option is a control that cannot do anything ΓÇö count
    // only the non-disabled entries, since the catalog itself always lists all four.
    const availableLanguageCount = (languages ?? []).filter((entry) => !entry.isDisabled).length
    const hasLanguages = availableLanguageCount > 1 && language != null && onLanguageChange != null

    // Identity hold: Toolbar does not accept CallerIdentity.
    return (
        <Toolbar
            leftTabs={{
                items,
                selectedKey: mode,
                ariaLabel,
                onSelectionChange: (key) => onModeChange(String(key) as ContentMode),
            }}
            rightTabs={
                hasLanguages
                    ? {
                        items: (languages ?? []).map((entry) => ({
                            key: entry.key,
                            label: entry.label,
                            icon: LANGUAGE_ICON,
                            isDisabled: entry.isDisabled,
                        })),
                        selectedKey: language as string,
                        ariaLabel: languageAriaLabel ?? "",
                        onSelectionChange: (key) => onLanguageChange?.(String(key)),
                    }
                    : undefined
            }
            // The language group is a "same lesson, different presentation" toggle, so
            // it stays NEUTRAL: only the mode group carries accent, and the row keeps
            // ONE accent signal rather than two competing for the eye.
            rightTabsNeutral
            // A set-once preference, not a second navigation choice ΓÇö folds behind a
            // compact icon-only dropdown below `@app-sm` instead of crowding the reading
            // column with 4 inline tabs.
            collapseRightOnMobile
        />
    )
}

export { ContentModeNav }

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * `CourseBrief` ΓÇö the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `┬╖`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     * Γ¢ö NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules ┬╖ ~14h ┬╖ 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator ΓÇö
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `┬╖`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) ΓÇö the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners ΓÇö the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` ΓåÆ the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data ΓÇö the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (┬º12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS ΓÇö units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (┬º14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={
                breadcrumbItems?.length
                    ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                        // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                        <div className="w-fit">
                            {/* collapse: below @app-sm or trail ΓëÑ 4 crumbs ΓåÆ back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={skeleton}
                            />
                        </div>
                    )
                    : undefined
            }
            title={title}
            description={description}
            meta={
                metaParts.length > 0
                    ? () => (
                        <Typography size="xs" color="muted" text={metaParts.join(" ┬╖ ")} />
                    )
                    : undefined
            }
        />
    )
}

/** `CourseBrief.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * BLOCK ΓÇö `CourseQaHeader`: the PAGE-IDENTITY cluster at the top of a course
 * Q&A screen ΓÇö trail, title, description, nothing else.
 *
 * SIBLING OF `LeaderboardHeader`/`FoundationsHeader`, NOT A COPY. Every ported
 * screen wraps `PageHeader` in its own domain-named block rather than the
 * screen touching the composite directly (rule 1). This board carries no meta
 * row for the same reason `LeaderboardHeader` doesn't: the facts (question
 * count, filter, sort) live in the honest-strip/toolbar below, not the header.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface CourseQaHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
