    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}
        />
    ))

    return (
        <nav className="sticky top-0 z-50 border-b border-default bg-surface">
            {/* primary row ΓÇö fixed 4rem tall, matching the real bar's height contract */}
            <div className="h-16 min-h-16">
                <StackH
                    principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups brand mark and desktop route pills on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            aria-label="StarCi Academy"
                                            onClick={onLogoPress}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") onLogoPress()
                                            }}
                                            className="inline-flex cursor-pointer"
                                        >
                                            <Logo />
                                        </span>
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <ButtonRadioGroup
                                                    items={navItems.map((item) => ({
                                                        value: item.id,
                                                        content: <Typography size="sm" text={item.label} />,
                                                    }))}
                                                    value={activeNavId}
                                                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                                                    ariaLabel="Main navigation"
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups search, locale, theme, cart, account, and mobile menu triggers on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <InputButtonLike
                                                    placeholder={searchPlaceholder}
                                                    icon={MagnifyingGlassIcon}
                                                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={MagnifyingGlassIcon}
                                                    ariaLabel={searchPlaceholder}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <StackH
                                                    principle="flex-action"
                                                    explain="Groups language and theme controls on one horizontal peer row so they share a single hit baseline."
                                                    items={[
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HeroButton
                                            isIconOnly
                                            variant="tertiary"
                                            className="rounded-full"
                                            aria-label="Cart"
                                            onPress={onCartPress}
                                        >
                                            <Badge color="accent" count={cartCount}>
                                                <ShoppingCartIcon className="size-5" />
                                            </Badge>
                                        </HeroButton>
                                    ),
                                    ...(account.isAuthed
                                        ? [
                                            () => (
                                                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                                                    <HeroButton
                                                        isIconOnly
                                                        variant="tertiary"
                                                        className="rounded-full"
                                                        aria-label="Notifications"
                                                    >
                                                        <Badge color="danger" count={notifications.unreadCount}>
                                                            <BellIcon className="size-5" />
                                                        </Badge>
                                                    </HeroButton>
                                                    <PopoverContent placement="bottom right" className="w-[360px]">
                                                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                                                        <StackV
                                                            principle="control-pad"
                                                            explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row."
                                                            items={[
                                                                () => (
                                                                    <StackH
                                                                        principle="sibling-stack"
                                                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        items={[
                                                                            () => <Typography size="sm" weight="bold" text="Notifications" />,
                                                                            ...(notifications.unreadCount > 0
                                                                                ? [
                                                                                    () => (
                                                                                        <Button
                                                                                            isIconOnly
                                                                                            variant="ghost"
                                                                                            size="sm"
                                                                                            prefixIcon={ChecksIcon}
                                                                                            ariaLabel="Mark all as read"
                                                                                            onPress={notifications.onMarkAllRead}
                                                                                        />
                                                                                    ),
                                                                                ]
                                                                                : []),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <AsyncContent
                                                                        isLoading={notifications.isLoading && notifications.items.length === 0}
                                                                        skeleton={() => (
                                                                            <StackV
                                                                                principle="sibling-stack"
                                                                                explain="Same-kind peer stack of notification skeleton rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                items={[() => notificationSkeletonRows]}
                                                                            />
                                                                        )}
                                                                        isEmpty={notifications.items.length === 0}
                                                                        emptyContent={{ title: "No notifications yet" }}
                                                                        error={notifications.error}
                                                                        errorContent={{
                                                                            title: notifications.error ?? "",
                                                                            onRetry: notifications.onRetry,
                                                                            retryLabel: "Try again",
                                                                        }}
                                                                        content={() => (
                                                                            <ScrollArea
                                                                                axis="y"
                                                                                principle="flex-fill"
                                                                                explain="Owns local vertical overflow for the notification list so long threads do not grow the popover past the viewport."
                                                                                body={() => (
                                                                                    <StackV
                                                                                        principle="sibling-stack"
                                                                                        explain="Same-kind peer stack of notification rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                        items={[() => notificationRows]}
                                                                                    />
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        label="See all"
                                                                        onPress={notifications.onSeeAll}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    </PopoverContent>
                                                </Popover>
                                            ),
                                        ]
                                        : []),
                                    () => (
                                        <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                                            <HeroButton
                                                isIconOnly
                                                variant="tertiary"
                                                className="rounded-full"
                                                aria-label="Account"
                                            >
                                                {account.isAuthed ? (
                                                    <Avatar
                                                        size="sm"
                                                        name={account.user?.username}
                                                        src={account.user?.avatarUrl ?? undefined}
                                                        seed={account.user?.email ?? account.user?.username}
                                                    />
                                                ) : (
                                                    <UserIcon className="size-5" />
                                                )}
                                            </HeroButton>
                                            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                                                <StackV
                                                    principle="cell-pad"
                                                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                    body={() => accountMenuHeader}
                                                />
                                                <Divider />
                                                <Dropdown.Menu aria-label="Account">
                                                    <Dropdown.Section>
                                                        {account.menuItems.map((item) => {
                                                            const Icon = item.icon
                                                            return (
                                                                <Dropdown.Item
                                                                    key={item.id}
                                                                    id={item.id}
                                                                    textValue={item.label}
                                                                    className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                                                    onPress={item.onPress}
                                                                >
                                                                    {Icon ? <Icon className="size-5" /> : null}
                                                                    <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                                                </Dropdown.Item>
                                                            )
                                                        })}
                                                    </Dropdown.Section>
                                                </Dropdown.Menu>
                                            </Dropdown.Popover>
                                        </Dropdown>
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={SidebarSimpleIcon}
                                                    ariaLabel="Open mobile menu"
                                                    onPress={() => onMobileDrawerOpenChange(true)}
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>

            {/* mobile navigation drawer ΓÇö the ONE local (non-overlay-store) drawer this run's
                contract calls for; every other overlay in this system opens through the global
                store (see canon Rule 13), this one is controlled straight by the caller. */}
            <DrawerShell
                isOpen={isMobileDrawerOpen}
                onOpenChange={onMobileDrawerOpenChange}
                placement="right"
                title="Mobile menu"
                body={() => (
                    <StackV
                        principle="group-boundary"
                        explain="Separates mobile route list from language/theme controls so each region keeps its own seam owner ΓÇö not sibling-stack, because these are distinct section roles rather than repeating peers."
                        items={[
                            () => (
                                <StackV
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of mobile route rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                    items={[() => mobileNavRows]}
                                />
                            ),
                            () => <Divider />,
                            () => (
                                <StackV
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of language and theme rows ΓÇö not group-boundary, because these are repeating preference peers rather than section groups."
                                    items={[
                                        () => (
                                            <StackH
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Typography size="sm" text="Language" />,
                                                    () => (
                                                        <NavbarLanguageMenu
                                                            languages={languages}
                                                            activeLocale={activeLocale}
                                                            onLocaleChange={onLocaleChange}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackH
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Typography size="sm" text="Theme" />,
                                                    () => (
                                                        <NavbarThemeSwitch
                                                            isDarkMode={isDarkMode}
                                                            onThemeToggle={onThemeToggle}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                        ]}
                    />
                )}
            />
        </nav>
    )
}

